import torch
from ptx_harness import ptx_load, ptx_launch

# PTX source for a row‑wise inclusive scan (cumulative sum) on fp16 data.
PTX_SOURCE = r"""
.version 8.0
.target sm_80
.address_size 64

.visible .entry scan_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 length
)
{
    // -------------------------------------------------
    // Registers
    // -------------------------------------------------
    .reg .pred   %p<6>;
    .reg .b32    %r<13>;
    .reg .b64    %rd<11>;
    .reg .f16    %fh0, %fh1;
    .reg .f32    %fs0, %fs1, %fs2, %fs3, %fs4, %fs5;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];
    ld.param.u32    %r1, [batch];
    ld.param.u32    %r2, [length];

    // -------------------------------------------------
    // Thread / block identifiers
    // -------------------------------------------------
    mov.u32 %r3, %tid.x;          // tid
    mov.u32 %r4, %ctaid.x;        // row index (blockIdx.x)
    mov.u32 %r5, %ntid.x;         // blockDim.x

    // -------------------------------------------------
    // Compute chunk size per thread: ceil(length / blockDim)
    // -------------------------------------------------
    add.u32 %r6, %r2, %r5;
    sub.u32 %r6, %r6, 1;
    div.u32 %r6, %r6, %r5;        // chunk = (length + blockDim -1) / blockDim

    // start = tid * chunk
    mul.lo.u32 %r7, %r3, %r6;
    // end = min(start + chunk, length)
    add.u32 %r8, %r7, %r6;
    setp.ge.u32 %p1, %r8, %r2;
    selp.u32 %r8, %r2, %r8, %p1; // end = (start+chunk > length) ? length : start+chunk

    // -------------------------------------------------
    // Shared memory for per‑thread sums and offsets
    // -------------------------------------------------
    .shared .align 4 .b8 sh_sums[256*4];
    .shared .align 4 .b8 sh_offsets[256*4];

    // -------------------------------------------------
    // First pass: compute per‑thread prefix (no offset) and store last value
    // -------------------------------------------------
    mov.f32 %fs0, 0f00000000;               // local sum = 0.0f
    mov.u32 %r9, %r7;                       // i = start

LOOP1:
    setp.ge.u32 %p2, %r9, %r8;
    @%p2 bra END_LOOP1;

    // address = input_ptr + ((row_offset + i) * 2)
    mul.lo.u64 %rd3, %r4, %r2;              // row_offset = row * length
    add.u64 %rd3, %rd3, %r9;                // row_offset + i
    mul.lo.u64 %rd3, %rd3, 2;               // *2 bytes (fp16)
    add.u64 %rd3, %rd1, %rd3;               // global address

    ld.global.u16 %r10, [%rd3];
    cvt.f16.u16 %fh0, %r10;
    cvt.f32.f16 %fs1, %fh0;                 // val_f

    add.f32 %fs0, %fs0, %fs1;               // sum += val

    // store prefix (without offset) to output
    mul.lo.u64 %rd4, %r4, %r2;
    add.u64 %rd4, %rd4, %r9;
    mul.lo.u64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd2, %rd4;

    cvt.f16.f32 %fh1, %fs0;
    cvt.u16.f16 %r11, %fh1;
    st.global.u16 [%rd4], %r11;

    add.u32 %r9, %r9, 1;
    bra LOOP1;
END_LOOP1:

    // write the final per‑thread sum to shared memory
    st.shared.f32 [sh_sums + %r3*4], %fs0;

    bar.sync 0;

    // -------------------------------------------------
    // Thread 0 computes exclusive offsets for all threads
    // -------------------------------------------------
    setp.eq.u32 %p3, %r3, 0;
    @%p3 {
        mov.f32 %fs2, 0f00000000;           // acc = 0.0f
        mov.u32 %r10, 0;                    // loop counter

OFFSET_LOOP:
        setp.ge.u32 %p4, %r10, %r5;
        @%p4 bra END_OFFSET_LOOP;

        ld.shared.f32 %fs3, [sh_sums + %r10*4];
        st.shared.f32 [sh_offsets + %r10*4], %fs2; // offset for thread r10
        add.f32 %fs2, %fs2, %fs3;                // acc += sum

        add.u32 %r10, %r10, 1;
        bra OFFSET_LOOP;
END_OFFSET_LOOP:
        // nothing
    }

    bar.sync 0;

    // load my exclusive offset
    ld.shared.f32 %fs4, [sh_offsets + %r3*4];

    // -------------------------------------------------
    // Second pass: add offset to previously written values
    // -------------------------------------------------
    mov.u32 %r9, %r7;                       // i = start again

LOOP2:
    setp.ge.u32 %p5, %r9, %r8;
    @%p5 bra END_LOOP2;

    // address of output element
    mul.lo.u64 %rd5, %r4, %r2;
    add.u64 %rd5, %rd5, %r9;
    mul.lo.u64 %rd5, %rd5, 2;
    add.u64 %rd5, %rd2, %rd5;

    ld.global.u16 %r10, [%rd5];
    cvt.f16.u16 %fh0, %r10;
    cvt.f32.f16 %fs5, %fh0;

    add.f32 %fs5, %fs5, %fs4;               // add exclusive offset

    cvt.f16.f32 %fh1, %fs5;
    cvt.u16.f16 %r11, %fh1;
    st.global.u16 [%rd5], %r11;

    add.u32 %r9, %r9, 1;
    bra LOOP2;
END_LOOP2:

    ret;
}
"""

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be fp16"
        assert self.dim == 1, "Only dim=1 (row‑wise) is supported in PTX implementation"
        batch = x.shape[0]
        length = x.shape[1] if x.dim() > 1 else 1

        y = torch.empty_like(x)

        grid = (batch, 1, 1)
        block = (256, 1, 1)

        args = [x.data_ptr(), y.data_ptr(), batch, length]
        ptx_launch(self.module, "scan_kernel", grid, block, args)

        return y
